import { useEffect, useMemo, useState } from 'react';
import { textbook } from './data/textbook';
import { courses } from './data/courses';
import { glossary } from './data/glossary';
import { chapterEnhancements } from './data/chapterEnhancements';
import { biologicalDeepening } from './data/biologicalDeepening';
import type { Section } from './types';
import QuestionBank from './components/QuestionBank';
import ScienceExplorer from './components/ScienceExplorer';

const STORAGE_KEY = 'bio21-progress-v1';
type SavedState = { completed:number[]; quizScores:Record<number,number>; learningSteps:Record<number,number[]>; quizAttempts:Record<number,number>; activeDates:string[] };
const initialState = ():SavedState => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<SavedState>;
      const completed = Array.isArray(parsed.completed) ? parsed.completed.filter((d): d is number => Number.isInteger(d) && d >= 1 && d <= 21) : [];
      const quizScores = parsed.quizScores && typeof parsed.quizScores === 'object' ? parsed.quizScores as Record<number, number> : {};
      const rawSteps = parsed.learningSteps && typeof parsed.learningSteps === 'object' ? parsed.learningSteps as Record<number, unknown> : {};
      const learningSteps:Record<number,number[]> = {};
      for (const [day,steps] of Object.entries(rawSteps)) { const d=Number(day); if (Number.isInteger(d)&&d>=1&&d<=21&&Array.isArray(steps)) learningSteps[d]=[...new Set(steps.filter((x):x is number=>Number.isInteger(x)&&x>=0&&x<=3))]; }
      const rawAttempts = parsed.quizAttempts && typeof parsed.quizAttempts === 'object' ? parsed.quizAttempts as Record<number,number> : {};
      const quizAttempts:Record<number,number> = {}; for (const [day,count] of Object.entries(rawAttempts)) { const d=Number(day); if (Number.isInteger(d)&&d>=1&&d<=21&&Number.isFinite(count)&&count>=0) quizAttempts[d]=Math.floor(count); }
      const activeDates = Array.isArray(parsed.activeDates) ? [...new Set(parsed.activeDates.filter((x):x is string=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)))].sort().slice(-120) : [];
      return { completed:[...new Set(completed)].sort((a,b)=>a-b), quizScores, learningSteps, quizAttempts, activeDates };
    }
  } catch { /* use defaults */ }
  return { completed:[], quizScores:{}, learningSteps:{}, quizAttempts:{}, activeDates:[] };
};
const phases = ['全部','生命基础','分子生物学','实验技术','生物制造','合成生物学','高级应用','综合项目'];
type LibraryState = { bookmarks:number[]; notes:Record<number,string> };
const LIBRARY_KEY = 'bio21-library-v1';
function readLibraryState():LibraryState { try { const raw=localStorage.getItem(LIBRARY_KEY); if(raw){const v=JSON.parse(raw) as Partial<LibraryState>; return {bookmarks:Array.isArray(v.bookmarks)?[...new Set(v.bookmarks.filter((d):d is number=>Number.isInteger(d)&&d>=1&&d<=21))]:[],notes:v.notes&&typeof v.notes==='object'?Object.fromEntries(Object.entries(v.notes).filter(([k,n])=>Number.isInteger(Number(k))&&Number(k)>=1&&Number(k)<=21&&typeof n==='string')) as Record<number,string>:{}};}} catch { /* local storage unavailable */ } return {bookmarks:[],notes:{}}; }

function App() {
  const [section,setSection] = useState<Section>('overview');
  const [saved,setSaved] = useState<SavedState>(initialState);
  const [library,setLibrary] = useState<LibraryState>(readLibraryState);
  const [libraryQuery,setLibraryQuery] = useState('');
  const [libraryFilter,setLibraryFilter] = useState<'all'|'bookmarks'|'notes'>('all');
  const [selectedDay,setSelectedDay] = useState(1);
  const [phase,setPhase] = useState('全部');
  const [query,setQuery] = useState('');
  const [quizChoice,setQuizChoice] = useState<number|null>(null);
  const [showAnswer,setShowAnswer] = useState(false);
  const [graphFocus,setGraphFocus] = useState<number|null>(null);
  const [labTab,setLabTab] = useState<'dna'|'pcr'|'fermentation'|'central'|'pcr-walkthrough'|'sanger'>('dna');
  const [dnaSequence,setDnaSequence] = useState('ATGCCGTA');
  const [pcrCycles,setPcrCycles] = useState(5);
  const [temperature,setTemperature] = useState(37);
  const [ph,setPh] = useState(6.8);
  const [oxygen,setOxygen] = useState(65);

  useEffect(() => { try { localStorage.setItem(STORAGE_KEY,JSON.stringify(saved)); } catch { /* storage may be disabled */ } },[saved]);
  useEffect(() => { try { localStorage.setItem(LIBRARY_KEY,JSON.stringify(library)); } catch { /* storage may be disabled */ } },[library]);
  const course = courses.find(c => c.day === selectedDay) ?? courses[0];
  const completed = saved.completed.length;
  const progress = Math.round(completed / courses.length * 100);
  const filteredCourses = courses.filter(c => (phase === '全部' || c.phase === phase) && `${c.title} ${c.subtitle} ${c.concepts.join(' ')}`.toLowerCase().includes(query.toLowerCase()));
  const filteredGlossary = useMemo(() => glossary.filter(g => `${g.term} ${g.group} ${g.definition}`.toLowerCase().includes(query.toLowerCase())),[query]);
  const libraryResults = useMemo(() => courses.filter(c => {
    const day=c.day; const book=textbook[day]; const extra=chapterEnhancements[day]; const note=library.notes[day]??'';
    const haystack=[c.title,c.subtitle,c.phase,c.summary,c.lesson.join(' '),book.heading,book.reading,book.workedExample,book.misconception,book.practice,extra.summary,extra.terms.map(t=>`${t.term} ${t.definition}`).join(' '),extra.review.map(r=>`${r.question} ${r.answer}`).join(' '),glossary.map(g=>`${g.term} ${g.group} ${g.definition}`).join(' '),note].join(' ').toLowerCase();
    const q=libraryQuery.trim().toLowerCase();
    return (!q||haystack.includes(q))&&(libraryFilter==='all'||(libraryFilter==='bookmarks'&&library.bookmarks.includes(day))||(libraryFilter==='notes'&&note.trim().length>0));
  }),[library,libraryQuery,libraryFilter]);
  const complementary = dnaSequence.toUpperCase().split('').map(base => (({A:'T',T:'A',G:'C',C:'G'} as Record<string,string>)[base] ?? '?')).join('');
  const safeSequence = /^[ATGC]*$/i.test(dnaSequence);
  const pcrCopies = Math.pow(2,pcrCycles);
  const tempScore = Math.max(0,100 - Math.abs(temperature - 30) * 2.8);
  const phScore = Math.max(0,100 - Math.abs(ph - 6.8) * 19);
  const fermentationScore = Math.round((tempScore * 0.35 + phScore * 0.4 + oxygen * 0.25));

  function markActive(prev:SavedState):SavedState { const now=new Date(); const today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`; return {...prev,activeDates:[...new Set([...prev.activeDates,today])].sort().slice(-120)}; }
  function openCourse(day:number) { setSaved(prev=>markActive(prev)); setSelectedDay(day); setQuizChoice(null); setShowAnswer(false); setSection('courses'); window.scrollTo({top:0,behavior:'smooth'}); }
  function toggleComplete(day:number) { setSaved(prev => markActive({...prev,completed:prev.completed.includes(day) ? prev.completed.filter(d=>d!==day) : [...prev.completed,day].sort((a,b)=>a-b)})); }
  function resetProgress() {
    if (window.confirm('确定要清除本设备上的 Bio21 学习进度和测验记录吗？')) {
      setSaved({ completed:[], quizScores:{}, learningSteps:{}, quizAttempts:{}, activeDates:[] });
      setSelectedDay(1);
      setQuizChoice(null);
      setShowAnswer(false);
    }
  }
  function toggleLearningStep(day:number,step:number) { setSaved(prev=>{ const current=prev.learningSteps[day]??[]; const next=current.includes(step)?current.filter(x=>x!==step):[...current,step]; return markActive({...prev,learningSteps:{...prev.learningSteps,[day]:next}}); }); }
  function submitQuiz() { if (quizChoice === null) return; setShowAnswer(true); setSaved(prev => markActive({...prev,quizScores:{...prev.quizScores,[course.day]:quizChoice===course.quiz.answer?1:0},quizAttempts:{...prev.quizAttempts,[course.day]:(prev.quizAttempts[course.day]??0)+1},learningSteps:{...prev.learningSteps,[course.day]:[...new Set([...(prev.learningSteps[course.day]??[]),3])]}})); }

  return <div className="app-shell">
    <aside className="sidebar">
      <button className="brand" onClick={()=>setSection('overview')} aria-label="返回首页"><span className="brand-mark">B<span>21</span></span><span className="brand-copy"><strong>Bio21</strong><small>生物工程学习实验室</small></span></button>
      <div className="sidebar-label">学习空间</div>
      <nav className="main-nav" aria-label="主导航">
        <NavButton active={section==='overview'} icon="◫" label="学习概览" onClick={()=>setSection('overview')} />
        <NavButton active={section==='courses'} icon="▤" label="21 天课程" onClick={()=>setSection('courses')} />
        <NavButton active={section==='lab'} icon="⌘" label="交互实验室" onClick={()=>setSection('lab')} />
        <NavButton active={section==='knowledge'} icon="⌘" label="知识关联图" onClick={()=>setSection('knowledge')} />
        <NavButton active={section==='science'} icon="✳" label="生物知识探索" onClick={()=>setSection('science')} />
        <NavButton active={section==='analytics'} icon="▥" label="学习分析" onClick={()=>setSection('analytics')} />
        <NavButton active={section==='glossary'} icon="⌕" label="术语知识库" onClick={()=>setSection('glossary')} />
        <NavButton active={section==='library'} icon="☆" label="教材书架" onClick={()=>setSection('library')} />
        <NavButton active={section==='practice'} icon="✓" label="章节题库" onClick={()=>setSection('practice')} />
      </nav>
      <div className="sidebar-progress"><div className="sidebar-progress-top"><span>学习进度</span><strong>{progress}%</strong></div><div className="progress-track"><span style={{width:`${progress}%`}} /></div><small>已完成 {completed} / 21 天</small></div>
      <div className="sidebar-bottom"><div className="leaf-icon">✳</div><p>好奇心是最好的实验工具。</p><small>每天一点，逐步建立系统认知。</small><button className="reset-progress" onClick={resetProgress}>重置本机学习进度</button></div>
    </aside>

    <main className="main-content">
      <header className="topbar"><div className="breadcrumb"><span>Bio21</span><i>/</i><strong>{({overview:'学习概览',courses:'21 天课程',lab:'交互实验室',knowledge:'知识关联图',science:'生物知识探索',analytics:'学习分析',glossary:'术语知识库',library:'教材书架',practice:'章节题库'} as Record<Section,string>)[section]}</strong></div><div className="topbar-right"><span className="status-dot"/> <span>个人学习空间</span><div className="avatar">B</div></div></header>
      {section==='overview' && <Overview completed={completed} progress={progress} saved={saved} openCourse={openCourse} setSection={setSection} />}
      {section==='courses' && <section className="page-section"><div className="page-heading"><div><div className="eyebrow">YOUR LEARNING PATH</div><h1>21 天，建立生物工程知识框架</h1><p>从细胞与遗传信息出发，逐步走向实验技术、生物制造与合成生物学。</p></div><div className="heading-stat"><strong>{completed}<small>/21</small></strong><span>课程已完成</span></div></div>
        <div className="course-workspace"><div className="course-list-panel"><div className="panel-toolbar"><label className="search-box"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索课程或知识点" /></label><select value={phase} onChange={e=>setPhase(e.target.value)} aria-label="课程阶段筛选">{phases.map(p=><option key={p}>{p}</option>)}</select></div><div className="course-list">{filteredCourses.map(c=><button key={c.day} className={`course-row ${selectedDay===c.day?'selected':''}`} onClick={()=>openCourse(c.day)}><span className={`day-number ${saved.completed.includes(c.day)?'done':''}`}>{saved.completed.includes(c.day)?'✓':String(c.day).padStart(2,'0')}</span><span className="course-row-copy"><small>{c.phase} · {c.duration}</small><strong>{c.title}</strong><span>{c.subtitle}</span></span><span className="row-arrow">›</span></button>)}{filteredCourses.length===0&&<div className="empty-state">没有找到匹配课程，试试其他关键词。</div>}</div></div>
        <article className="lesson-panel"><div className="lesson-topline"><span className="lesson-day">DAY {String(course.day).padStart(2,'0')}</span><span className="level-tag">{course.level}</span></div><div className="lesson-illustration"><div className="molecule m1"/><div className="molecule m2"/><div className="molecule m3"/><div className="helix"><span/><span/><span/><span/><span/><span/></div><div className="illustration-caption">BIOLOGY · ENGINEERING · DESIGN</div></div><div className="lesson-content"><div className="eyebrow">{course.phase.toUpperCase()}</div><h2>{course.title}</h2><p className="lesson-subtitle">{course.subtitle}</p><div className="concept-tags">{course.concepts.map(x=><span key={x}>{x}</span>)}</div><p className="lesson-summary">{course.summary}</p><DiagramAtlas day={course.day} /><div className="textbook-tools"><button className={`button-secondary ${library.bookmarks.includes(course.day)?'is-bookmarked':''}`} onClick={()=>setLibrary(prev=>({...prev,bookmarks:prev.bookmarks.includes(course.day)?prev.bookmarks.filter(d=>d!==course.day):[...prev.bookmarks,course.day]}))}>{library.bookmarks.includes(course.day)?'★ 已加入书签':'☆ 收藏本章'}</button><span>笔记与书签仅保存在当前浏览器</span></div><div className="textbook-section"><div className="textbook-kicker">TEXTBOOK CHAPTER · DAY {String(course.day).padStart(2,'0')}</div><h3>{textbook[course.day].heading}</h3><p className="textbook-intro">本章学习目标</p><ul className="textbook-objectives">{textbook[course.day].objectives.map((objective,i)=><li key={objective}><span>{String(i+1).padStart(2,'0')}</span>{objective}</li>)}</ul><h4>深入阅读</h4><p className="textbook-prose">{textbook[course.day].reading}</p><div className="textbook-example"><span>案例解析</span><p>{textbook[course.day].workedExample}</p></div><div className="textbook-misconception"><span>易错点与边界</span><p>{textbook[course.day].misconception}</p></div><div className="textbook-practice"><span>课后思考</span><p>{textbook[course.day].practice}</p></div><div className="chapter-summary"><span className="chapter-extra-kicker">CHAPTER SUMMARY</span><h4>本章小结</h4><p>{chapterEnhancements[course.day].summary}</p></div><section className="biology-deepening"><div className="chapter-extra-kicker">BIOLOGY CONCEPTS · MECHANISM TO EVIDENCE</div><h4>生物知识深化</h4><p className="biology-deepening-intro">不只记结论：理解机制、区分相近概念，并知道证据能支持到什么程度。</p><div className="biology-deepening-grid"><article><span>01 · 作用机制</span><p>{biologicalDeepening[course.day].mechanism}</p></article><article><span>02 · 概念辨析</span><p>{biologicalDeepening[course.day].distinction}</p></article><article><span>03 · 工程应用</span><p>{biologicalDeepening[course.day].application}</p></article><article><span>04 · 证据与边界</span><p>{biologicalDeepening[course.day].evidence}</p></article></div></section><div className="chapter-terms"><h4>关键术语</h4><div className="chapter-term-list">{chapterEnhancements[course.day].terms.map(item=><div className="chapter-term" key={item.term}><button className="term-link" onClick={()=>{setQuery(item.term);setSection('glossary');window.scrollTo({top:0,behavior:'smooth'});}}>{item.term} ↗</button><p>{item.definition}</p></div>)}</div></div><div className="chapter-review"><h4>复习与自测</h4>{chapterEnhancements[course.day].review.map((item,i)=><details className="chapter-review-item" key={item.question}><summary><span>{String(i+1).padStart(2,'0')}</span>{item.question}</summary><p>{item.answer}</p></details>)}</div><a className="textbook-resource" href={textbook[course.day].furtherReading.url} target="_blank" rel="noreferrer">延伸阅读：{textbook[course.day].furtherReading.title} ↗</a></div><div className="chapter-notes"><div><h3>我的本章笔记</h3><p>记录疑问、关键结论或复习计划。</p></div><textarea aria-label="本章个人笔记" value={library.notes[course.day]??''} onChange={e=>setLibrary(prev=>({...prev,notes:{...prev.notes,[course.day]:e.target.value}}))} placeholder="例如：我需要进一步理解引物如何决定扩增区域……" rows={4}/><div className="notes-foot"><span>{(library.notes[course.day]??'').length} 个字符 · 自动保存在本机</span><button className="text-button" onClick={()=>setLibrary(prev=>{const notes={...prev.notes};delete notes[course.day];return {...prev,notes};})}>清空本章笔记</button></div></div><h3>本节核心知识</h3><ul className="lesson-points">{course.lesson.map((line,i)=><li key={line}><span>{String(i+1).padStart(2,'0')}</span>{line}</li>)}</ul><div className="task-card"><div className="task-icon">✳</div><div><strong>今日小任务</strong><p>{course.task}</p></div></div><div className="learning-loop"><div className="learning-loop-head"><div><div className="eyebrow">LEARNING LOOP</div><h3>本节学习闭环</h3></div><span>{(saved.learningSteps[course.day]??[]).length}/4 已完成</span></div><div className="learning-loop-grid">{[{title:'理解概念',desc:'阅读本节核心知识',icon:'01'},{title:'观察演示',desc:'打开相关交互模型',icon:'02'},{title:'动手探索',desc:'调整参数并观察结果',icon:'03'},{title:'检验理解',desc:'完成下方知识测验',icon:'04'}].map((step,i)=><button key={step.title} className={`loop-step ${(saved.learningSteps[course.day]??[]).includes(i)?'is-done':''}`} onClick={()=>{toggleLearningStep(course.day,i);if(i===1||i===2){setLabTab(course.day>=7&&course.day<=10?'pcr':course.day>=13&&course.day<=15?'fermentation':'central');setSection('lab');}}}><span className="loop-step-icon">{(saved.learningSteps[course.day]??[]).includes(i)?'✓':step.icon}</span><strong>{step.title}</strong><small>{step.desc}</small></button>)}</div><p className="loop-note">学习步骤保存在本机浏览器。点击步骤可标记完成；“观察演示”和“动手探索”会同时打开交互实验室。</p></div><div className="quiz-card"><div className="quiz-title"><span>知识检查</span><small>单选 · 即时反馈</small></div><h3>{course.quiz.question}</h3><div className="quiz-options">{course.quiz.options.map((option,i)=><button key={option} disabled={showAnswer} className={`quiz-option ${showAnswer&&i===course.quiz.answer?'correct':showAnswer&&i===quizChoice?'incorrect':quizChoice===i?'chosen':''}`} onClick={()=>setQuizChoice(i)}><span className="option-letter">{String.fromCharCode(65+i)}</span>{option}<span className="option-check">{showAnswer&&i===course.quiz.answer?'✓':showAnswer&&i===quizChoice?'×':''}</span></button>)}</div>{showAnswer&&<div className={`answer-feedback ${quizChoice===course.quiz.answer?'good':'bad'}`}><strong>{quizChoice===course.quiz.answer?'回答正确':'再复习一下'}</strong><p>{course.quiz.explanation}</p></div>}<button className="button-primary quiz-submit" onClick={submitQuiz} disabled={quizChoice===null||showAnswer}>{showAnswer?'已提交答案':'提交答案'} <span>→</span></button></div><div className="lesson-footer"><button className="text-button" onClick={()=>openCourse(Math.max(1,course.day-1))} disabled={course.day===1}><span>←</span> 上一课</button><button className={`button-secondary ${saved.completed.includes(course.day)?'completed-button':''}`} onClick={()=>toggleComplete(course.day)}>{saved.completed.includes(course.day)?'✓ 已标记完成':'○ 标记为已完成'}</button><button className="text-button" onClick={()=>openCourse(Math.min(21,course.day+1))} disabled={course.day===21}>下一课 <span>→</span></button></div></div></article></div>
      </section>}
      {section==='lab' && <Lab labTab={labTab} setLabTab={setLabTab} dnaSequence={dnaSequence} setDnaSequence={setDnaSequence} complementary={complementary} safeSequence={safeSequence} pcrCycles={pcrCycles} setPcrCycles={setPcrCycles} pcrCopies={pcrCopies} temperature={temperature} setTemperature={setTemperature} ph={ph} setPh={setPh} oxygen={oxygen} setOxygen={setOxygen} fermentationScore={fermentationScore} />}
      {section==='knowledge' && <KnowledgeMap completed={saved.completed} graphFocus={graphFocus} setGraphFocus={setGraphFocus} openCourse={openCourse} />}
      {section==='science' && <ScienceExplorer openCourse={openCourse} openQuestionBank={()=>setSection('practice')} />}
      {section==='analytics' && <LearningAnalytics saved={saved} openCourse={openCourse} setSection={setSection} />}
      {section==='glossary' && <section className="page-section"><div className="page-heading"><div><div className="eyebrow">BIO21 KNOWLEDGE BASE</div><h1>术语知识库</h1><p>把关键概念串联起来。搜索术语，快速建立学科词汇表。</p></div><div className="heading-stat"><strong>{glossary.length}<small>+</small></strong><span>核心术语</span></div></div><label className="glossary-search search-box"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索术语、类别或解释……"/><kbd>⌕</kbd></label><div className="glossary-grid">{filteredGlossary.map((item,i)=><article className="glossary-card" key={item.term}><div className="glossary-card-top"><span className="glossary-index">{String(i+1).padStart(2,'0')}</span><span className="glossary-group">{item.group}</span></div><h3>{item.term}</h3><p>{item.definition}</p></article>)}</div>{filteredGlossary.length===0&&<div className="empty-state">没有找到匹配术语。</div>}</section>}
      {section==='practice' && <QuestionBank openCourse={openCourse} />}
      {section==='library' && <section className="page-section library-page"><div className="page-heading"><div><div className="eyebrow">PERSONAL TEXTBOOK LIBRARY</div><h1>教材书架</h1><p>全文检索 21 章教材、保存章节书签，并整理个人学习笔记。</p></div><div className="heading-stat"><strong>{library.bookmarks.length}<small>/21</small></strong><span>已收藏章节</span></div></div><label className="glossary-search search-box"><span>⌕</span><input value={libraryQuery} onChange={e=>setLibraryQuery(e.target.value)} placeholder="搜索课程、正文、案例、术语或复习题……"/><kbd>⌕</kbd></label><div className="library-filter-row"><button className={libraryFilter==='all'?'active':''} onClick={()=>setLibraryFilter('all')}>全部内容</button><button className={libraryFilter==='bookmarks'?'active':''} onClick={()=>setLibraryFilter('bookmarks')}>★ 我的书签（{library.bookmarks.length}）</button><button className={libraryFilter==='notes'?'active':''} onClick={()=>setLibraryFilter('notes')}>✎ 我的笔记（{Object.values(library.notes).filter(n=>n.trim()).length}）</button><button className="button-secondary export-notes" onClick={()=>{const blob=new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),bookmarks:library.bookmarks,notes:library.notes},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='bio21-my-learning-notes.json';a.click();URL.revokeObjectURL(url);}}>导出 JSON ↓</button><button className="button-secondary" onClick={()=>{const body=courses.map(c=>`# Day ${String(c.day).padStart(2,'0')} · ${c.title}\n\n${library.notes[c.day]?.trim()||'（暂无个人笔记）'}\n`).join('\n---\n\n');const blob=new Blob([`# Bio21 学习笔记\n\n导出时间：${new Date().toLocaleString()}\n\n${body}`],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='bio21-learning-notes.md';a.click();URL.revokeObjectURL(url);}}>导出 Markdown ↓</button><label className="button-secondary import-notes">导入备份 ↑<input aria-label="导入 Bio21 笔记备份" type="file" accept=".json,application/json" onChange={async e=>{const input=e.currentTarget;const file=input.files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text()) as {bookmarks?:unknown;notes?:unknown};if(!parsed||typeof parsed!=='object'||!Array.isArray(parsed.bookmarks)||!parsed.notes||typeof parsed.notes!=='object'||Array.isArray(parsed.notes))throw new Error('format');const bookmarks=[...new Set(parsed.bookmarks.filter((d):d is number=>Number.isInteger(d)&&d>=1&&d<=21))];const notes=Object.fromEntries(Object.entries(parsed.notes as Record<string,unknown>).filter(([k,v])=>Number.isInteger(Number(k))&&Number(k)>=1&&Number(k)<=21&&typeof v==='string')) as Record<number,string>;setLibrary(prev=>({bookmarks:[...new Set([...prev.bookmarks,...bookmarks])],notes:{...prev.notes,...notes}}));window.alert(`导入成功：${bookmarks.length} 个书签、${Object.keys(notes).length} 章笔记。已有同章节笔记会被备份内容覆盖。`);}catch{window.alert('导入失败：文件格式不正确。请选择 Bio21 导出的 JSON 备份。');}finally{input.value='';}}}/></label></div><div className="library-results">{libraryResults.map(c=>{const day=c.day;const book=textbook[day];const note=library.notes[day]??'';return <article className="library-result" key={day}><div className="library-result-top"><span className="lesson-day">DAY {String(day).padStart(2,'0')}</span><span>{c.phase}</span>{library.bookmarks.includes(day)&&<span className="library-star">★ 已收藏</span>}</div><h2>{c.title}</h2><p className="library-subtitle">{book.heading} · {c.subtitle}</p><p>{book.reading}</p><div className="library-result-tags">{chapterEnhancements[day].terms.map(t=><span key={t.term}>{t.term}</span>)}</div>{note.trim()&&<div className="library-note-preview"><strong>我的笔记</strong><p>{note.length>180?`${note.slice(0,180)}…`:note}</p></div>}<div className="library-result-actions"><button className="button-primary" onClick={()=>openCourse(day)}>打开本章 →</button><button className="button-secondary" onClick={()=>setLibrary(prev=>({...prev,bookmarks:prev.bookmarks.includes(day)?prev.bookmarks.filter(d=>d!==day):[...prev.bookmarks,day]}))}>{library.bookmarks.includes(day)?'移除书签':'☆ 收藏章节'}</button></div></article>;})}{libraryResults.length===0&&<div className="empty-state">没有找到匹配内容。试试更短的关键词，或切换书签/笔记筛选。</div>}</div><p className="library-disclaimer">搜索范围包括课程标题、教材正文、案例、易错点、章节术语、复习问题和个人笔记。书签与笔记保存在本机浏览器，不会自动同步到其他设备。</p></section>}
      <footer className="footer"><span>Bio21 · 生物工程 21 天学习实验室</span><span>学习进度保存在当前浏览器中 <i>·</i> 科普学习用途</span></footer>
    </main>
  </div>;
}

const knowledgePhases = [
 {name:'生命基础',range:'01–03',days:[1,2,3],desc:'细胞、生命分子与遗传基础',color:'sage'},
 {name:'分子生物学',range:'04–06',days:[4,5,6],desc:'DNA、基因表达与调控',color:'blue'},
 {name:'实验技术',range:'07–12',days:[7,8,9,10,11,12],desc:'PCR、测序、检测与数据',color:'amber'},
 {name:'生物制造',range:'13–15',days:[13,14,15],desc:'发酵、放大与过程控制',color:'coral'},
 {name:'合成生物学',range:'16–18',days:[16,17,18],desc:'设计、构建、测试与学习',color:'violet'},
 {name:'高级应用',range:'19–21',days:[19,20,21],desc:'应用场景、安全与综合项目',color:'dark'}
];
function KnowledgeMap({completed,graphFocus,setGraphFocus,openCourse}:{completed:number[];graphFocus:number|null;setGraphFocus:(d:number|null)=>void;openCourse:(d:number)=>void}) {
 const focused = graphFocus===null ? null : courses.find(c=>c.day===graphFocus)??null;
 return <section className="page-section knowledge-page"><div className="page-heading"><div><div className="eyebrow">CONCEPT CONNECTIONS</div><h1>知识关联图</h1><p>生物工程知识不是孤立的章节。沿着“生命基础 → 分子机制 → 实验方法 → 工程应用”建立联系。</p></div><div className="heading-stat"><strong>{completed.length}<small>/21</small></strong><span>已完成节点</span></div></div>
 <div className="knowledge-banner"><div><span className="eyebrow">HOW TO USE</span><h2>选择一个知识节点，查看课程并继续学习</h2><p>每个节点都对应 21 天课程中的一节。连线表示建议的学习先后关系，不代表唯一的知识依赖路径。</p></div><div className="knowledge-banner-mark">DNA <span>↔</span> DATA <span>↔</span> DESIGN</div></div>
 <div className="knowledge-flow"><div className="knowledge-flow-line" aria-hidden="true"/>{knowledgePhases.map((phase,pi)=><div className={`knowledge-phase ${phase.color}`} key={phase.name}><div className="knowledge-phase-head"><span className="phase-index">0{pi+1}</span><div><h3>{phase.name}</h3><p>{phase.desc}</p></div><small>{phase.range}</small></div><div className="knowledge-nodes">{phase.days.map(day=>{const c=courses[day-1];return <button key={day} className={`knowledge-node ${completed.includes(day)?'done':''} ${graphFocus===day?'focused':''}`} onClick={()=>setGraphFocus(graphFocus===day?null:day)}><span className="knowledge-node-day">{completed.includes(day)?'✓':String(day).padStart(2,'0')}</span><strong>{c.title}</strong><small>{c.concepts.slice(0,2).join(' · ')}</small></button>})}</div></div>)}</div>
 {focused&&<div className="knowledge-detail"><div><span className="eyebrow">DAY {String(focused.day).padStart(2,'0')} · {focused.phase}</span><h2>{focused.title}</h2><p>{focused.summary}</p><div className="concept-tags">{focused.concepts.map(x=><span key={x}>{x}</span>)}</div></div><button className="button-primary" onClick={()=>openCourse(focused.day)}>打开课程 <span>→</span></button></div>}
 <div className="knowledge-legend"><span><i className="legend-dot completed-dot"/> 已完成</span><span><i className="legend-dot selected-dot"/> 当前选中</span><span><i className="legend-dot pending-dot"/> 待学习</span><span className="knowledge-caution">路线用于辅助理解，具体知识关系以课程内容为准。</span></div>
 </section>;
}

function DiagramAtlas({day}:{day:number}) {
  const [active,setActive]=useState<'dna'|'flow'|'cell'|'reactor'>(day>=13&&day<=15?'reactor':day>=7&&day<=12?'dna':day<=6?'cell':'flow');
  const tabs:[typeof active,string,string][]=[['dna','DNA 双链','配对与方向'],['flow','中心法则','DNA → RNA → 蛋白质'],['cell','细胞结构','区室与功能'],['reactor','生物反应器','混合与传质']];
  return <section className="diagram-atlas"><div className="diagram-heading"><div><span className="eyebrow">VISUAL LEARNING ATLAS</span><h3>本章配套图解</h3><p>切换图解，建立分子结构与工程过程的视觉联系。</p></div><span className="diagram-count">4 个模型</span></div><div className="diagram-tabs" role="tablist" aria-label="图解类型">{tabs.map(([id,title,sub])=><button key={id} role="tab" aria-selected={active===id} className={active===id?'active':''} onClick={()=>setActive(id)}><strong>{title}</strong><small>{sub}</small></button>)}</div><div className="diagram-canvas">
    {active==='dna'&&<><svg viewBox="0 0 620 210" role="img" aria-label="DNA 双链碱基互补配对示意图"><defs><linearGradient id="dnaA" x1="0" x2="1"><stop stopColor="#6ca77a"/><stop offset="1" stopColor="#a6c9a0"/></linearGradient><linearGradient id="dnaB" x1="0" x2="1"><stop stopColor="#d7a35b"/><stop offset="1" stopColor="#f0d3a1"/></linearGradient></defs><path d="M70 35 C160 35 160 175 250 175 S340 35 430 35 S520 175 570 175" fill="none" stroke="url(#dnaA)" strokeWidth="6" strokeLinecap="round"/><path d="M70 175 C160 175 160 35 250 35 S340 175 430 175 S520 35 570 35" fill="none" stroke="url(#dnaB)" strokeWidth="6" strokeLinecap="round"/>{Array.from({length:9},(_,i)=>{const x=90+i*55;const y1=65+Math.sin(i*.8)*35;const y2=145-Math.sin(i*.8)*35;return <g key={i}><line x1={x} y1={y1} x2={x} y2={y2} stroke="#b9c6b5" strokeWidth="2"/><text x={x} y={y1-8} textAnchor="middle" fill="#42714a" fontSize="12" fontWeight="700">{['A','T','G','C'][i%4]}</text><text x={x} y={y2+17} textAnchor="middle" fill="#a27538" fontSize="12" fontWeight="700">{({'A':'T','T':'A','G':'C','C':'G'} as Record<string,string>)[['A','T','G','C'][i%4]]}</text></g>})}<text x="28" y="20" fill="#7b8a7b" fontSize="11">5′</text><text x="580" y="198" fill="#7b8a7b" fontSize="11">3′</text></svg><p className="diagram-caption">A–T、G–C 互补配对；两条 DNA 链方向相反。图中曲线为概念示意，不按真实分子尺度绘制。</p></>}
    {active==='flow'&&<><svg viewBox="0 0 620 210" role="img" aria-label="DNA 转录 RNA 翻译蛋白质信息流图"><defs><marker id="flowArrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#739776"/></marker></defs>{[{x:28,title:'DNA',sub:'遗传信息',fill:'#e4efe1',stroke:'#7fa67b'},{x:238,title:'mRNA',sub:'转录产物',fill:'#f8eedc',stroke:'#d5ad68'},{x:448,title:'蛋白质',sub:'功能执行',fill:'#e8e3f3',stroke:'#9b8ac6'}].map(n=><g key={n.title}><rect x={n.x} y="60" width="145" height="82" rx="15" fill={n.fill} stroke={n.stroke} strokeWidth="2"/><text x={n.x+72} y="96" textAnchor="middle" fontSize="20" fontWeight="700" fill="#334d38">{n.title}</text><text x={n.x+72} y="119" textAnchor="middle" fontSize="12" fill="#68786a">{n.sub}</text></g>)}<path d="M177 101 H224" stroke="#739776" strokeWidth="3" markerEnd="url(#flowArrow)"/><path d="M387 101 H434" stroke="#739776" strokeWidth="3" markerEnd="url(#flowArrow)"/><text x="200" y="82" textAnchor="middle" fill="#6b846d" fontSize="11">转录</text><text x="410" y="82" textAnchor="middle" fill="#6b846d" fontSize="11">翻译</text><text x="310" y="177" textAnchor="middle" fill="#7a897b" fontSize="12">经典信息流概括；逆转录等过程需单独理解</text></svg><p className="diagram-caption">DNA 可经转录生成 RNA；mRNA 可在核糖体参与下被翻译为多肽。并非所有 RNA 都编码蛋白质。</p></>}
    {active==='cell'&&<><svg viewBox="0 0 620 210" role="img" aria-label="真核细胞主要结构示意图"><ellipse cx="300" cy="105" rx="245" ry="82" fill="#edf4e9" stroke="#7ca17a" strokeWidth="3"/><ellipse cx="285" cy="105" rx="67" ry="49" fill="#e1e9f5" stroke="#8aa5cc" strokeWidth="2"/><circle cx="285" cy="105" r="21" fill="#9fb5da"/><g fill="#d8b578" stroke="#b38b4e" strokeWidth="1.5"><ellipse cx="165" cy="85" rx="25" ry="11" transform="rotate(-25 165 85)"/><ellipse cx="390" cy="132" rx="27" ry="12" transform="rotate(18 390 132)"/><ellipse cx="370" cy="70" rx="20" ry="9" transform="rotate(-12 370 70)"/></g><g fill="#7da785"><circle cx="210" cy="137" r="4"/><circle cx="415" cy="93" r="4"/><circle cx="440" cy="120" r="4"/><circle cx="225" cy="69" r="4"/></g><g fontSize="12" fill="#425b47"><text x="72" y="28">细胞膜</text><path d="M98 32 L110 50" stroke="#799b78"/><text x="275" y="31">细胞核</text><path d="M302 36 L292 55" stroke="#799b78"/><text x="440" y="174">线粒体（示意）</text><path d="M442 158 L410 139" stroke="#799b78"/></g></svg><p className="diagram-caption">细胞图解为真核细胞的简化概念模型；不同细胞类型在形态、细胞器组成和功能上存在差异。</p></>}
    {active==='reactor'&&<><svg viewBox="0 0 620 210" role="img" aria-label="生物反应器搅拌和通气示意图"><path d="M220 28 Q220 18 235 18 H355 Q370 18 370 28 V155 Q370 177 348 177 H242 Q220 177 220 155 Z" fill="#eef5e9" stroke="#759b76" strokeWidth="3"/><path d="M223 91 H367 V155 Q367 174 348 174 H242 Q223 174 223 155 Z" fill="#c6dfc0"/><line x1="295" y1="18" x2="295" y2="142" stroke="#667b69" strokeWidth="5"/><path d="M267 95 H323 M278 120 H312" stroke="#667b69" strokeWidth="6" strokeLinecap="round"/><path d="M258 143 Q295 155 332 143" fill="none" stroke="#5f9bc4" strokeWidth="3" strokeDasharray="5 5"/><g fill="#fff" stroke="#6ba2c5" strokeWidth="2">{[[253,127],[280,137],[312,131],[337,143],[271,153]].map(([x,y],i)=><circle key={i} cx={x} cy={y} r="4"/>)}</g><g fontSize="12" fill="#425b47"><text x="45" y="55">搅拌与混合</text><path d="M133 59 L263 96" stroke="#799b78" strokeWidth="1.5"/><text x="415" y="55">通气与传质</text><path d="M415 60 L337 138" stroke="#799b78" strokeWidth="1.5"/><text x="238" y="199">生物反应器（概念示意）</text></g></svg><p className="diagram-caption">实际反应器性能还受几何结构、流体性质、气液传质、剪切、热量交换和控制策略影响。</p></>}
  </div></section>;
}

function NavButton({active,icon,label,onClick}:{active:boolean;icon:string;label:string;onClick:()=>void}) { return <button className={`nav-button ${active?'active':''}`} onClick={onClick}><span className="nav-icon">{icon}</span>{label}{active&&<span className="nav-active-dot"/>}</button>; }

function Overview({completed,progress,saved,openCourse,setSection}:{completed:number;progress:number;saved:SavedState;openCourse:(day:number)=>void;setSection:(s:Section)=>void}) {
 const nextDay = courses.find(c=>!saved.completed.includes(c.day))?.day ?? 21;
 const phaseCounts = [{name:'生命基础',range:'01 — 03',days:[1,2,3],color:'sage',desc:'认识生命系统的结构、能量与分子基础'},{name:'分子生物学',range:'04 — 07',days:[4,5,6,7],color:'blue',desc:'理解遗传信息如何储存、读取与调控'},{name:'实验技术',range:'08 — 12',days:[8,9,10,11,12],color:'amber',desc:'从实验设计走向常见分析技术'},{name:'生物制造',range:'13 — 15',days:[13,14,15],color:'coral',desc:'理解发酵、放大生产与质量控制'},{name:'合成生物学',range:'16 — 18',days:[16,17,18],color:'violet',desc:'用工程化方法设计与迭代生物系统'},{name:'高级应用',range:'19 — 21',days:[19,20,21],color:'dark',desc:'连接医药、诊断、安全与项目实践'}];
 return <section className="overview-page"><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line"/> YOUR BIOLOGY JOURNEY</div><h1>让好奇心，<em>成为生产力。</em></h1><p>从基础生命科学到生物工程应用，循序渐进地理解这个正在改变世界的领域。</p></div><div className="welcome-orbit"><div className="orbit-ring ring-one"/><div className="orbit-ring ring-two"/><div className="orbit-core">BIO<span>21</span></div><span className="orbit-dot dot-one"/><span className="orbit-dot dot-two"/><span className="orbit-dot dot-three"/></div></div>
 <div className="hero-stats"><div className="hero-stat"><span className="stat-icon green">◷</span><div><strong>21 <small>天</small></strong><span>结构化学习路径</span></div></div><div className="hero-stat"><span className="stat-icon blue">⌘</span><div><strong>06 <small>阶段</small></strong><span>从基础到综合应用</span></div></div><div className="hero-stat"><span className="stat-icon yellow">✳</span><div><strong>03 <small>模拟</small></strong><span>交互式概念实验</span></div></div><div className="hero-stat"><span className="stat-icon lilac">✓</span><div><strong>{completed.toString().padStart(2,'0')} <small>/ 21</small></strong><span>已完成课程</span></div></div></div>
 <div className="overview-columns"><div className="path-section"><div className="section-title-row"><div><div className="eyebrow">THE ROADMAP</div><h2>你的学习路线</h2></div><button className="text-button" onClick={()=>setSection('courses')}>查看全部课程 <span>→</span></button></div><div className="phase-grid">{phaseCounts.map((p,i)=>{const done=p.days.filter(d=>saved.completed.includes(d)).length;return <button key={p.name} className="phase-card" onClick={()=>openCourse(p.days.find(d=>!saved.completed.includes(d))??p.days[0])}><div className={`phase-art ${p.color}`}><span className="phase-art-num">0{i+1}</span><span className="phase-art-symbol">{['◉','⌬','⌁','◌','✳','◇'][i]}</span><span className="phase-art-range">{p.range}</span></div><div className="phase-card-body"><div className="phase-card-heading"><h3>{p.name}</h3><span>{done}/{p.days.length}</span></div><p>{p.desc}</p><div className="mini-progress"><span style={{width:`${done/p.days.length*100}%`}}/></div></div></button>})}</div></div>
 <aside className="continue-card"><div className="continue-top"><span className="eyebrow">PICK UP WHERE YOU LEFT OFF</span><span className="continue-spark">✳</span></div><div className="continue-visual"><div className="visual-cell cell-a"/><div className="visual-cell cell-b"/><div className="visual-cell cell-c"/><div className="visual-cell cell-d"/><div className="visual-line line-a"/><div className="visual-line line-b"/><div className="visual-line line-c"/><div className="visual-orbit"/></div><div className="continue-content"><span className="day-pill">DAY {String(nextDay).padStart(2,'0')} · {courses[nextDay-1].phase}</span><h3>{courses[nextDay-1].title}</h3><p>{courses[nextDay-1].subtitle}</p><div className="continue-progress-row"><span>整体学习进度</span><strong>{progress}%</strong></div><div className="progress-track large"><span style={{width:`${progress}%`}}/></div><button className="button-primary continue-button" onClick={()=>openCourse(nextDay)}>继续学习 <span>→</span></button><button className="lab-shortcut" onClick={()=>setSection('lab')}><span>⌘</span><span><strong>打开交互实验室</strong><small>DNA · PCR · 发酵模拟</small></span><b>↗</b></button></div></aside></div>
 <div className="bottom-note"><span className="note-icon">✳</span><div><strong>学习建议</strong><p>每天完成一节课程，先理解概念，再做知识检查。模拟器用于理解原理，并不替代真实实验培训或实验室安全规范。</p></div><button onClick={()=>setSection('glossary')}>浏览术语库 <span>→</span></button></div>
 </section>;
}

function LearningAnalytics({saved,openCourse,setSection}:{saved:SavedState;openCourse:(day:number)=>void;setSection:(s:Section)=>void}) {
 const attempts=Object.values(saved.quizAttempts).reduce((a,b)=>a+b,0);
 const answered=Object.keys(saved.quizScores).length;
 const correct=Object.values(saved.quizScores).reduce((a,b)=>a+b,0);
 const accuracy=answered?Math.round(correct/answered*100):0;
 const wrongDays=courses.filter(c=>saved.quizScores[c.day]===0).map(c=>c.day);
 const today=new Date();
 const dateKey=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 const activeSet=new Set(saved.activeDates);
 let streak=0; const cursor=new Date(today); if(!activeSet.has(dateKey(cursor))) cursor.setDate(cursor.getDate()-1); while(activeSet.has(dateKey(cursor))&&streak<120){streak++;cursor.setDate(cursor.getDate()-1)}
 const last14=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(13-i));return {key:dateKey(d),label:`${d.getMonth()+1}/${d.getDate()}`,active:activeSet.has(dateKey(d))}});
 const stepCount=Object.values(saved.learningSteps).reduce((sum,steps)=>sum+steps.length,0);
 const phaseMastery = [...new Set(courses.map(c=>c.phase))].map(name=>{
   const items=courses.filter(c=>c.phase===name);
   const completedCount=items.filter(c=>saved.completed.includes(c.day)).length;
   const answeredItems=items.filter(c=>saved.quizScores[c.day]!==undefined);
   const correctItems=answeredItems.filter(c=>saved.quizScores[c.day]===1).length;
   const score=items.length?Math.round((completedCount/items.length*60)+(answeredItems.length?correctItems/answeredItems.length*40:0)):0;
   return {name,items,completedCount,answeredItems:answeredItems.length,correctItems,score};
 });
 const weakestPhase=[...phaseMastery].sort((a,b)=>a.score-b.score)[0];
 function exportLearningReport(format:'json'|'md') {
   const generatedAt=new Date().toLocaleString();
   const report={title:'Bio21 个人学习报告',generatedAt,overall:{completedCourses:saved.completed.length,totalCourses:21,completionPercent:Math.round(saved.completed.length/21*100),quizAccuracy:accuracy,answeredChapters:answered,totalAttempts:attempts,activeDays:saved.activeDates.length,learningSteps:stepCount},phaseMastery:phaseMastery.map(({name,items,completedCount,answeredItems,correctItems,score})=>({phase:name,totalCourses:items.length,completedCourses:completedCount,answeredChapters:answeredItems,correctAnswers:correctItems,masteryScore:score})),courseResults:courses.map(c=>({day:c.day,title:c.title,phase:c.phase,completed:saved.completed.includes(c.day),latestQuiz:saved.quizScores[c.day]===undefined?'未作答':saved.quizScores[c.day]===1?'正确':'错误',attempts:saved.quizAttempts[c.day]??0,learningSteps:(saved.learningSteps[c.day]??[]).length})),recommendation:weakestPhase?`优先复习「${weakestPhase.name}」阶段，并完成尚未作答或答错章节。`:'开始第一节课程并完成章节测验，建立个人学习记录。'};
   const content=format==='json'?JSON.stringify(report,null,2):`# Bio21 个人学习报告

- 生成时间：${generatedAt}
- 课程完成：${report.overall.completedCourses}/21（${report.overall.completionPercent}%）
- 章节测验正确率：${accuracy}%（${correct}/${answered} 个已作答章节最近结果）
- 答题总次数：${attempts}
- 有记录的学习天数：${saved.activeDates.length}
- 学习闭环步骤：${stepCount}/84

## 阶段掌握度

| 阶段 | 完成课程 | 已答章节 | 正确题数 | 综合掌握度 |
|---|---:|---:|---:|---:|
${phaseMastery.map(x=>`| ${x.name} | ${x.completedCount}/${x.items.length} | ${x.answeredItems} | ${x.correctItems} | ${x.score}% |`).join('\n')}

## 逐章记录

| Day | 课程 | 完成 | 最近测验 | 答题次数 | 学习步骤 |
|---:|---|---|---|---:|---:|
${report.courseResults.map(x=>`| ${x.day} | ${x.title} | ${x.completed?'是':'否'} | ${x.latestQuiz} | ${x.attempts} | ${x.learningSteps}/4 |`).join('\n')}

## 下一步建议

${report.recommendation}

> 本报告基于当前浏览器保存的学习记录生成。掌握度是便于自我检查的启发式指标，不是标准化考试成绩。`;
   const blob=new Blob([content],{type:format==='json'?'application/json;charset=utf-8':'text/markdown;charset=utf-8'});
   const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=format==='json'?'bio21-learning-report.json':'bio21-learning-report.md';a.click();URL.revokeObjectURL(url);
 }
 return <section className="page-section analytics-page"><div className="page-heading"><div><div className="eyebrow">YOUR LEARNING INSIGHTS</div><h1>学习分析</h1><p>查看学习进度、活跃记录与测验表现，找到下一步值得复习的内容。</p></div><button className="button-secondary" onClick={()=>setSection('courses')}>继续课程 →</button></div>
 <div className="analytics-metrics"><article className="analytics-metric"><span>课程完成率</span><strong>{Math.round(saved.completed.length/21*100)}<small>%</small></strong><div className="analytics-bar"><i style={{width:`${saved.completed.length/21*100}%`}}/></div><small>{saved.completed.length} / 21 节已完成</small></article><article className="analytics-metric"><span>当前连续学习</span><strong>{streak}<small> 天</small></strong><p>根据本设备保存的活跃日期计算</p></article><article className="analytics-metric"><span>测验正确率</span><strong>{accuracy}<small>%</small></strong><p>{correct} / {answered} 节课程的最近一次答题正确</p></article><article className="analytics-metric"><span>答题总次数</span><strong>{attempts}<small> 次</small></strong><p>包含重复练习；仅保存每节课最近一次结果</p></article></div>
 <article className="analytics-panel mastery-report-panel"><div className="analytics-panel-heading"><div><span className="eyebrow">PERSONAL LEARNING REPORT</span><h2>阶段掌握度与学习报告</h2><p>综合课程完成度与最近一次章节测验结果估算阶段掌握度；未作答章节不会被视为答对。</p></div><div className="report-actions"><button className="button-secondary" onClick={()=>exportLearningReport('md')}>导出 Markdown ↓</button><button className="button-primary" onClick={()=>exportLearningReport('json')}>导出 JSON ↓</button></div></div><div className="mastery-list">{phaseMastery.map(item=><div className="mastery-row" key={item.name}><div className="mastery-label"><strong>{item.name}</strong><small>{item.completedCount}/{item.items.length} 节完成 · {item.answeredItems} 节已测验</small></div><div className="mastery-track"><span style={{width:`${item.score}%`}} /></div><strong className="mastery-score">{item.score}%</strong></div>)}</div><div className="mastery-recommendation"><span>下一步建议</span><p>{weakestPhase?`优先复习「${weakestPhase.name}」阶段。该阶段当前估算掌握度为 ${weakestPhase.score}%；可先补齐未完成课程，再重做答错题目。`:'开始第一节课程并完成章节测验，系统将根据本机记录生成阶段学习建议。'}</p><button className="text-button" onClick={()=>weakestPhase?openCourse(weakestPhase.items.find(c=>!saved.completed.includes(c.day))?.day??weakestPhase.items[0].day):setSection('courses')}>开始复习 →</button></div></article>
 <div className="analytics-columns"><article className="analytics-panel"><div className="analytics-panel-heading"><div><span className="eyebrow">LAST 14 DAYS</span><h2>学习活跃记录</h2></div><span className="analytics-badge">{saved.activeDates.length} 个记录日</span></div><div className="activity-grid">{last14.map(day=><div key={day.key} className={`activity-day ${day.active?'active':''}`} title={`${day.key}${day.active?' · 有学习活动':' · 无记录'}`}><span>{day.label}</span><i>{day.active?'✓':''}</i></div>)}</div><p className="analytics-footnote">活跃日表示在本机进行过课程或测验操作，不代表精确学习时长。日期使用设备本地日期。</p></article><article className="analytics-panel"><div className="analytics-panel-heading"><div><span className="eyebrow">LEARNING LOOP</span><h2>学习闭环完成情况</h2></div></div><div className="loop-progress-total"><strong>{stepCount}</strong><span>/ 84 个步骤记录</span></div><div className="analytics-bar wide"><i style={{width:`${Math.min(100,stepCount/84*100)}%`}}/></div><p className="analytics-footnote">21 节课程 × 每节 4 个步骤。步骤由用户手动标记；答题提交会自动记录“检验理解”。</p><button className="text-button" onClick={()=>setSection('knowledge')}>查看知识关联图 →</button></article></div>
 <article className="analytics-panel review-panel"><div className="analytics-panel-heading"><div><span className="eyebrow">REVIEW QUEUE</span><h2>建议复习</h2><p>这里列出最近一次测验答错的课程。再次提交正确答案后，该课程会从此列表移除。</p></div><span className="analytics-badge">{wrongDays.length} 节待复习</span></div>{wrongDays.length? <div className="review-list">{wrongDays.map(day=>{const c=courses[day-1];return <div key={day} className="review-item"><span className="review-day">DAY {String(day).padStart(2,'0')}</span><div><strong>{c.title}</strong><small>{c.phase} · 已尝试 {saved.quizAttempts[day]??0} 次</small></div><button className="button-secondary" onClick={()=>openCourse(day)}>重新学习 →</button></div>})}</div>:<div className="review-empty"><span>✓</span><strong>暂时没有待复习课程</strong><p>完成课程测验后，答错的题目会自动出现在这里。</p><button className="button-primary" onClick={()=>openCourse(courses.find(c=>!saved.completed.includes(c.day))?.day??21)}>继续学习 →</button></div>}</article>
 <div className="analytics-disclaimer">数据仅保存在当前浏览器。清除浏览器站点数据或更换设备后，记录可能丢失；目前没有账号同步与云端备份。</div></section>;
}

function Lab(props:{labTab:'dna'|'pcr'|'fermentation'|'central'|'pcr-walkthrough'|'sanger';setLabTab:(t:'dna'|'pcr'|'fermentation'|'central'|'pcr-walkthrough'|'sanger')=>void;dnaSequence:string;setDnaSequence:(s:string)=>void;complementary:string;safeSequence:boolean;pcrCycles:number;setPcrCycles:(n:number)=>void;pcrCopies:number;temperature:number;setTemperature:(n:number)=>void;ph:number;setPh:(n:number)=>void;oxygen:number;setOxygen:(n:number)=>void;fermentationScore:number}) {
 const {labTab,setLabTab,dnaSequence,setDnaSequence,complementary,safeSequence,pcrCycles,setPcrCycles,pcrCopies,temperature,setTemperature,ph,setPh,oxygen,setOxygen,fermentationScore}=props;
 return <section className="page-section lab-page"><div className="page-heading"><div><div className="eyebrow">INTERACTIVE BIOLOGY</div><h1>交互实验室</h1><p>通过简化的可视化模型，探索分子生物学与生物制造中的核心概念。</p></div><div className="lab-status"><span className="status-dot"/> 模型运行中</div></div><div className="lab-tabs">{([{id:'dna',label:'DNA 互补链',sub:'BASE PAIRING'},{id:'central',label:'中心法则',sub:'DNA → RNA → PROTEIN'},{id:'pcr',label:'PCR 扩增',sub:'AMPLIFICATION'},{id:'pcr-walkthrough',label:'PCR 三阶段',sub:'DENATURE · ANNEAL · EXTEND'},{id:'sanger',label:'Sanger 测序',sub:'SEQUENCE READING'},{id:'fermentation',label:'发酵参数',sub:'BIOPROCESS'}] as const).map(t=><button key={t.id} className={labTab===t.id?'active':''} onClick={()=>setLabTab(t.id)}><span>{t.label}</span><small>{t.sub}</small></button>)}</div>
 {labTab==='central'&&<CentralDogmaLesson/>}
 {labTab==='pcr-walkthrough'&&<PCRWalkthrough/>}
 {labTab==='sanger'&&<SangerLesson/>}
 {labTab==='dna'&&<div className="lab-card"><div className="lab-card-heading"><div><span className="eyebrow">MODEL 01</span><h2>DNA 碱基互补配对</h2><p>输入一段 DNA 序列，观察互补链如何依据碱基配对规则生成。</p></div><span className="lab-chip">A—T · G—C</span></div><label className="sequence-label">DNA 序列 <small>仅支持 A / T / G / C</small></label><input className="sequence-input" value={dnaSequence} maxLength={32} onChange={e=>setDnaSequence(e.target.value.toUpperCase())} aria-label="输入 DNA 序列"/><div className="sequence-meta"><span>{dnaSequence.length} bp · 碱基对</span><span className={safeSequence?'valid-text':'error-text'}>{safeSequence?'序列格式有效':'包含无效字符，请只输入 A、T、G、C'}</span></div><div className="dna-visual"><div className="strand-label">5′ → 3′ <span>模板链示意</span></div><div className="base-row">{dnaSequence.split('').map((base,i)=><span key={i} className={`base base-${base}`}>{base}</span>)}</div><div className="pair-lines">{dnaSequence.split('').map((_,i)=><span key={i} className="pair-line"/>)}</div><div className="base-row complement-row">{complementary.split('').map((base,i)=><span key={i} className={`base base-${base}`}>{base}</span>)}</div><div className="strand-label bottom">3′ ← 5′ <span>互补链示意</span></div></div><div className="pair-legend"><span><i className="base-A"/> A 腺嘌呤</span><span><i className="base-T"/> T 胸腺嘧啶</span><span><i className="base-G"/> G 鸟嘌呤</span><span><i className="base-C"/> C 胞嘧啶</span></div><div className="lab-explain"><strong>原理提示</strong><p>DNA 的互补配对规则为 A–T、G–C。这里展示的是概念模型；真实 DNA 结构还包含反向平行的糖-磷酸骨架等信息。</p></div></div>}
 {labTab==='pcr'&&<div className="lab-card"><div className="lab-card-heading"><div><span className="eyebrow">MODEL 02</span><h2>PCR 理想化扩增</h2><p>调节循环次数，观察理想条件下目标 DNA 分子数量的指数增长。</p></div><span className="lab-chip">2ⁿ 理想模型</span></div><div className="pcr-visual"><div className="pcr-orbit"><div className="pcr-core">DNA</div><span className="pcr-node n1">变性</span><span className="pcr-node n2">退火</span><span className="pcr-node n3">延伸</span><div className="pcr-ring"/></div><div className="pcr-metric"><small>理论分子数（从 1 个起始模板计算）</small><strong>{pcrCopies.toLocaleString('en-US')}</strong><span>2<sup>{pcrCycles}</sup> copies</span><div className="pcr-bars">{Array.from({length:Math.min(pcrCycles+1,12)},(_,i)=><div key={i} style={{height:`${Math.max(7,Math.pow(2,i)/Math.pow(2,Math.min(pcrCycles,11))*100)}%`}} title={`第 ${i} 轮`}/>)}</div></div></div><div className="slider-field"><div><label htmlFor="pcr-cycles">扩增循环次数</label><strong>{pcrCycles} cycles</strong></div><input id="pcr-cycles" type="range" min="1" max="20" value={pcrCycles} onChange={e=>setPcrCycles(Number(e.target.value))}/><div className="slider-ends"><span>1 轮</span><span>20 轮</span></div></div><div className="lab-explain"><strong>理解模型边界</strong><p>真实 PCR 不会无限保持 100% 扩增效率；试剂消耗、产物再退火和抑制因素会让扩增逐渐进入平台期。本模拟仅用于展示理想指数增长。</p></div></div>}
 {labTab==='fermentation'&&<div className="lab-card"><div className="lab-card-heading"><div><span className="eyebrow">MODEL 03</span><h2>发酵过程参数探索</h2><p>调节温度、pH 与溶氧，查看教学用的相对适宜度指标如何变化。</p></div><span className="lab-chip">教学模拟</span></div><div className="fermentation-layout"><div className="ferment-vessel"><div className="vessel-label">BIOREACTOR <span>SIMULATION</span></div><div className="vessel"><div className="vessel-liquid" style={{height:`${Math.max(20,oxygen)}%`}}/><div className="vessel-bubbles"><i/><i/><i/><i/><i/></div><div className="vessel-shaft"/><div className="vessel-blade"/><div className="vessel-scale">{oxygen}%</div></div><div className="vessel-base"/><div className="vessel-caption">相对溶氧示意</div></div><div className="ferment-controls"><div className="ferment-score"><div><small>相对适宜度</small><strong>{fermentationScore}<span>/100</span></strong></div><div className="score-ring" style={{background:`conic-gradient(var(--green) ${fermentationScore*3.6}deg,#e5ebe5 0deg)`}}><span>{fermentationScore>=80?'良好':fermentationScore>=55?'一般':'偏低'}</span></div></div><SliderControl label="温度" value={temperature} min={10} max={45} step={1} suffix="°C" onChange={setTemperature}/><SliderControl label="pH 值" value={ph} min={4} max={9} step={0.1} suffix="" onChange={setPh}/><SliderControl label="相对溶氧" value={oxygen} min={0} max={100} step={1} suffix="%" onChange={setOxygen}/><p className="model-disclaimer">适宜度公式为演示用的简化假设，并不对应任何具体菌株或真实生产工艺。</p></div></div><div className="lab-explain"><strong>工程视角</strong><p>生物反应器的实际表现取决于生物体、培养基、传质、混合与控制策略等多因素。真实工艺应依据目标系统的数据和验证结果设定参数。</p></div></div>}
 </section>;
}
const centralSteps = [
 {title:'DNA：保存信息',tag:'遗传信息库',desc:'DNA 的碱基序列保存遗传信息。细胞需要表达某个基因时，会在相应调控机制下启动转录。',symbol:'DNA',color:'dna'},
 {title:'转录：DNA → RNA',tag:'转录',desc:'RNA 聚合酶以 DNA 的一条链为模板合成 RNA。RNA 的序列与编码链相近，但通常以 U 替代 T。',symbol:'mRNA',color:'rna'},
 {title:'翻译：RNA → 蛋白质',tag:'翻译',desc:'核糖体读取 mRNA 上的密码子，tRNA 携带相应氨基酸，逐步形成多肽链。',symbol:'RIBOSOME',color:'protein'},
 {title:'蛋白质：执行功能',tag:'折叠与功能',desc:'多肽链折叠并可能经过修饰后形成具有特定结构与功能的蛋白质。蛋白质参与催化、运输、信号和结构支持等过程。',symbol:'PROTEIN',color:'protein'}
];
function CentralDogmaLesson(){
 const [step,setStep]=useState(0); const item=centralSteps[step];
 return <div className="lab-card animation-card"><div className="lab-card-heading"><div><span className="eyebrow">ANIMATED LESSON 01</span><h2>分子生物学中心法则</h2><p>逐步查看遗传信息如何从 DNA 经过 RNA 传递到蛋白质。</p></div><span className="lab-chip">信息流</span></div>
 <div className={`central-stage stage-${item.color}`}><div className="central-molecule molecule-left"><span>{step===0?'A T G C':step===1?'A U G C':step===2?'AUG · GCU':'NH₂'}</span><small>{step===0?'DNA 双链':step===1?'信使 RNA':step===2?'密码子':'多肽链'}</small></div><div className="central-flow"><span className="flow-arrow">{step===0?'→':step===1?'→':step===2?'→':'✓'}</span><small>{item.tag}</small></div><div className="central-molecule molecule-right"><span>{item.symbol}</span><small>{['遗传信息','RNA 转录本','氨基酸序列','具有功能的蛋白质'][step]}</small></div><div className="central-orbit orbit-a"/><div className="central-orbit orbit-b"/></div>
 <div className="animation-step-meta"><span>STEP {step+1} / {centralSteps.length}</span><strong>{item.title}</strong></div><p className="animation-description">{item.desc}</p><div className="step-dots">{centralSteps.map((x,i)=><button key={x.title} className={step===i?'active':''} onClick={()=>setStep(i)} aria-label={`查看步骤 ${i+1}`}/>)}</div><div className="animation-actions"><button className="button-secondary" onClick={()=>setStep(s=>Math.max(0,s-1))} disabled={step===0}>← 上一步</button><button className="button-primary" onClick={()=>setStep(s=>(s+1)%centralSteps.length)}>{step===centralSteps.length-1?'重新播放':'下一步'} →</button></div><div className="lab-explain"><strong>准确性提示</strong><p>中心法则是信息流的经典概括，并不表示所有生物过程都只有这一条路径；例如逆转录可将 RNA 信息复制为 DNA。</p></div></div>
}
const pcrStages=[
 {name:'变性',temp:'约 94–98°C',desc:'加热使双链 DNA 的两条链分开，成为后续反应的模板。',color:'denature'},
 {name:'退火',temp:'常见约 50–65°C',desc:'降温后，引物与互补的目标序列结合。具体温度取决于引物性质与实验体系。',color:'anneal'},
 {name:'延伸',temp:'常用约 72°C（Taq）',desc:'耐热 DNA 聚合酶从引物末端开始延伸，合成新的 DNA 链。酶的类型会影响适宜温度。',color:'extend'}
];
function PCRWalkthrough(){const [step,setStep]=useState(0);const [cycle,setCycle]=useState(1);const stage=pcrStages[step];return <div className="lab-card animation-card"><div className="lab-card-heading"><div><span className="eyebrow">ANIMATED LESSON 02</span><h2>PCR：一个循环的三个阶段</h2><p>点击阶段按钮，观察模板链在变性、退火和延伸过程中的变化。</p></div><span className="lab-chip">热循环</span></div><div className={`pcr-stage-visual ${stage.color}`}><div className="pcr-dna-strand strand-one"><i/><i/><i/><i/><i/><i/><i/><i/></div><div className="pcr-dna-strand strand-two"><i/><i/><i/><i/><i/><i/><i/><i/></div>{step>0&&<div className="pcr-primers"><span>引物</span><span>引物</span></div>}{step===2&&<div className="polymerase-pill">DNA 聚合酶 →</div>}<div className="pcr-temp-pill">{stage.temp}</div></div><div className="pcr-stage-buttons">{pcrStages.map((x,i)=><button key={x.name} className={step===i?'active':''} onClick={()=>setStep(i)}><span>0{i+1}</span><strong>{x.name}</strong></button>)}</div><h3 className="animation-subtitle">{stage.name} · {stage.temp}</h3><p className="animation-description">{stage.desc}</p><div className="cycle-counter"><span>教学循环计数</span><strong>{cycle}</strong><button className="button-secondary" onClick={()=>{setCycle(c=>c+1);setStep(0)}}>完成一轮循环 +1</button><button className="text-button" onClick={()=>{setCycle(1);setStep(0)}}>重置</button></div><div className="lab-explain"><strong>重要说明</strong><p>温度仅为常见教学范围，不是适用于所有试剂、引物和样本的操作配方。真实实验必须遵循试剂说明、经验证的方案与实验室安全要求。</p></div></div>}
const sangerSteps=[
 {title:'准备单链模板与引物',desc:'将待测 DNA 模板、测序引物、DNA 聚合酶、常规 dNTP 和少量带标记的 ddNTP 放入反应体系。',label:'反应准备'},
 {title:'随机终止链延伸',desc:'当荧光标记 ddNTP 被掺入新链时，由于缺少 3′-OH，链不能继续延伸，因此形成不同长度的片段。',label:'ddNTP 终止'},
 {title:'按片段长度分离',desc:'毛细管电泳使短片段通常先于长片段通过检测窗口；片段末端的荧光标记指示末端碱基类型。',label:'毛细管电泳'},
 {title:'读取荧光信号',desc:'仪器记录片段通过检测窗口时的荧光颜色与顺序，再推断新合成链的 5′→3′ 序列。',label:'信号转序列'}
];
function SangerLesson(){const [step,setStep]=useState(0);const item=sangerSteps[step];const colors=['#5b9b75','#d7a64e','#648fba','#b779a8'];return <div className="lab-card animation-card"><div className="lab-card-heading"><div><span className="eyebrow">ANIMATED LESSON 03</span><h2>Sanger 链终止测序</h2><p>从链终止到毛细管分离，再到荧光信号读取，逐步理解测序原理。</p></div><span className="lab-chip">DNA 测序</span></div><div className={`sanger-stage sanger-step-${step}`}><div className="sanger-lane"><span className="lane-label">DNA 模板</span><div className="template-bases">A T G C C A T G</div><div className="template-line"/></div><div className="sanger-fragments">{Array.from({length:step===0?2:step===1?5:step===2?7:8},(_,i)=><div key={i} className="sanger-fragment" style={{width:`${28+i*7}%`,animationDelay:`${i*80}ms`}}><span style={{background:colors[i%4]}}>{['A','C','G','T'][i%4]}</span><i/></div>)}</div>{step>=2&&<div className="sanger-detector"><span className="detector-light"/><strong>{step===2?'毛细管分离':'荧光检测器'}</strong><small>{step===2?'短片段先通过':'记录颜色与到达顺序'}</small></div>}</div><div className="animation-step-meta"><span>STEP {step+1} / {sangerSteps.length}</span><strong>{item.title}</strong></div><p className="animation-description">{item.desc}</p><div className="sanger-signal-row"><span>示意碱基峰</span>{['A','C','G','T','C','A','T','G'].slice(0,step===3?8:Math.max(2,step*2+2)).map((b,i)=><span key={i} className="signal-base" style={{borderColor:colors[['A','C','G','T'].indexOf(b)]}}>{b}</span>)}</div><div className="animation-actions"><button className="button-secondary" onClick={()=>setStep(s=>Math.max(0,s-1))} disabled={step===0}>← 上一步</button><button className="button-primary" onClick={()=>setStep(s=>(s+1)%sangerSteps.length)}>{step===sangerSteps.length-1?'重新播放':'下一步'} →</button></div><div className="lab-explain"><strong>序列方向</strong><p>测序仪输出通常表示新合成链的 5′→3′ 方向。实际色谱图需要结合峰质量、混峰和测序读长等信息判读；此处为教学示意，不代表真实测序数据。</p></div></div>}

function SliderControl({label,value,min,max,step,suffix,onChange}:{label:string;value:number;min:number;max:number;step:number;suffix:string;onChange:(v:number)=>void}) { return <div className="slider-field compact"><div><label>{label}</label><strong>{value.toFixed(step<1?1:0)}{suffix}</strong></div><input aria-label={label} type="range" min={min} max={max} step={step} value={value} onChange={e=>onChange(Number(e.target.value))}/><div className="slider-ends"><span>{min}{suffix}</span><span>{max}{suffix}</span></div></div>; }

export default App;
